import type { InstallId, OriginId } from '@geo/domain';
import { createInstallId, createOriginId, systemRandomBytes, type RandomBytes } from './ids.ts';

export interface InstallIdentity {
  readonly installId: InstallId;
  readonly origin: OriginId;
}

// The origin tells merged histories apart; it is not the experiment install id
// (FE01 behaviour 1). Both are regenerated by "Delete everything".
export function createInstallIdentity(
  at: number,
  random: RandomBytes = systemRandomBytes,
): InstallIdentity {
  return {
    installId: createInstallId(at, random),
    origin: createOriginId(at, random),
  };
}
